while (z >= 0)
    sum += z;

question.en:
What happens in the following snippet if `z` is initially 5?
while (z >= 0)
    sum += z;

example.code:
#include <iostream>
#include <iomanip>

int main() {
    unsigned int total{175};
    unsigned int count{4};

    // static_cast prevents integer division truncation
    double average{static_cast<double>(total) / count};

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Average: " << average << std::endl;
    return 0;
}

#include <iostream>

int main() {
    unsigned int x{5};
    unsigned int product{5};
    product *= x++; // product = 5 * 5 = 25; x becomes 6
    std::cout << "product: " << product << ", x: " << x << std::endl;

    x = 5;
    unsigned int quotient{30};
    quotient /= ++x; // x becomes 6; quotient = 30 / 6 = 5
    std::cout << "quotient: " << quotient << ", x: " << x << std::endl;
    return 0;
}

#include <iostream>

int main() {
    unsigned int x{0};
    unsigned int y{0};

    if (std::cin >> x >> y) {
        unsigned int i{1};
        unsigned int power{1};

        while (i <= y) {
            power *= x;
            ++i;
        }

        std::cout << power << std::endl;
    }
    return 0;
}
